#define _XOPEN_SOURCE 700

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>

#include "fileio.h"
#include "json.h"
#include "path.h"
#include "platform.h"
#include "rewrite.h"
#include "util.h"

struct edit {
	size_t start, end;
	char *text;		/* the replacement; empty removes */
};

/*
 * A projects key or a githubRepoPaths element. Whether it changes depends
 * on its neighbours, so it is decided when its container closes.
 */
struct item {
	size_t start, end;	/* raw bytes, quotes included */
	char *value;		/* NULL when not a string */
	char *new_value;	/* NULL when it stays */
	char *field;
};

struct item_list {
	struct item *items;
	size_t count, cap;
};

struct range {
	size_t start, end;
};

struct github_list {
	struct github_path *items;
	size_t count, cap;
};

struct scan {
	const char *text;
	enum rewrite_kind kind;
	const struct rewrite_rules *rules;
	const char *file;
	size_t line;
	struct change_list changes;
	struct edit *edits;
	size_t edit_count, edit_cap;
	struct item_list keys;
	struct item_list elems;
	const char *drop;	/* githubRepoPaths elements to drop, in order */
	size_t drop_index;
	struct github_list *github;	/* config_github_paths collects here */
};

static char *dup_or_null(const char *s)
{
	return s != NULL ? xstrdup(s) : NULL;
}

static void add_change(struct change_list *list, enum change_kind kind,
    const char *file, size_t line, const char *field, const char *old_value,
    const char *new_value)
{
	struct change *c;

	if (list->count == list->cap) {
		list->cap = list->cap ? list->cap * 2 : 16;
		list->items = xrealloc(list->items, list->cap * sizeof *c);
	}
	c = &list->items[list->count++];
	c->kind = kind;
	c->file = dup_or_null(file);
	c->line = line;
	c->field = xstrdup(field);
	c->old_value = xstrdup(old_value);
	c->new_value = dup_or_null(new_value);
}

void change_list_free(struct change_list *list)
{
	size_t i;

	for (i = 0; i < list->count; i++) {
		free(list->items[i].file);
		free(list->items[i].field);
		free(list->items[i].old_value);
		free(list->items[i].new_value);
	}
	free(list->items);
	list->items = NULL;
	list->count = list->cap = 0;
}

/* Takes ownership of text. */
static void add_edit(struct scan *sc, size_t start, size_t end, char *text)
{
	if (sc->edit_count == sc->edit_cap) {
		sc->edit_cap = sc->edit_cap ? sc->edit_cap * 2 : 16;
		sc->edits = xrealloc(sc->edits,
		    sc->edit_cap * sizeof *sc->edits);
	}
	sc->edits[sc->edit_count].start = start;
	sc->edits[sc->edit_count].end = end;
	sc->edits[sc->edit_count].text = text;
	sc->edit_count++;
}

/* Takes ownership of value, new_value and field. */
static void add_item(struct item_list *list, const struct json_token *tok,
    char *value, char *new_value, char *field)
{
	struct item *it;

	if (list->count == list->cap) {
		list->cap = list->cap ? list->cap * 2 : 16;
		list->items = xrealloc(list->items, list->cap * sizeof *it);
	}
	it = &list->items[list->count++];
	it->start = tok->start;
	it->end = tok->end;
	it->value = value;
	it->new_value = new_value;
	it->field = field;
}

static void clear_items(struct item_list *list)
{
	size_t i;

	for (i = 0; i < list->count; i++) {
		free(list->items[i].value);
		free(list->items[i].new_value);
		free(list->items[i].field);
	}
	list->count = 0;
}

/* The first variant of the project path that value matches decides. */
char *rewrite_project_path(const struct path_pair *pairs, size_t count,
    const char *value)
{
	char *out;
	size_t i;

	for (i = 0; i < count; i++) {
		out = path_move(value, pairs[i].old_path, pairs[i].new_path, 0);
		if (out != NULL)
			return out;
	}
	return NULL;
}

static char *move_project(const struct rewrite_rules *rules, const char *value)
{
	return rewrite_project_path(rules->projects, rules->project_count,
	    value);
}

static char *move_session_dir(const struct rewrite_rules *rules,
    const char *value)
{
	if (rules->old_session_dir == NULL)
		return NULL;
	return path_move(value, rules->old_session_dir, rules->new_session_dir,
	    1);
}

static char *append(char *s, const char *t)
{
	size_t n, m;

	n = strlen(s);
	m = strlen(t);
	s = xrealloc(s, n + m + 1);
	memcpy(s + n, t, m + 1);
	return s;
}

static int is_identifier(const char *s)
{
	if (!((*s >= 'A' && *s <= 'Z') || (*s >= 'a' && *s <= 'z') ||
	    *s == '_'))
		return 0;
	for (s++; *s != '\0'; s++)
		if (!((*s >= 'A' && *s <= 'Z') || (*s >= 'a' && *s <= 'z') ||
		    (*s >= '0' && *s <= '9') || *s == '_'))
			return 0;
	return 1;
}

/* The way to a value for people: cwd, message.content[0].x, a["o/r"][1]. */
static char *field_name(const struct json_seg *path, size_t depth)
{
	char *out, *enc, num[32];
	size_t i;

	out = xstrdup("");
	for (i = 0; i < depth; i++) {
		if (path[i].key == NULL) {
			snprintf(num, sizeof num, "[%zu]", path[i].index);
			out = append(out, num);
		} else if (is_identifier(path[i].key)) {
			if (i > 0)
				out = append(out, ".");
			out = append(out, path[i].key);
		} else {
			enc = json_encode_string(path[i].key);
			out = append(out, "[\"");
			out = append(out, enc);
			out = append(out, "\"]");
			free(enc);
		}
	}
	return out;
}

static char *token_string(const struct scan *sc, const struct json_token *tok)
{
	return json_decode_string(sc->text + tok->start + 1,
	    tok->end - tok->start - 2);
}

/* Replaces the body of a string token and records the change. */
static void rewrite_token(struct scan *sc, const struct json_token *tok,
    const char *old_value, const char *new_value)
{
	char *field;

	field = field_name(tok->path, tok->depth);
	add_edit(sc, tok->start + 1, tok->end - 1, json_encode_string(new_value));
	add_change(&sc->changes, CHANGE_REWRITE, sc->file, sc->line, field,
	    old_value, new_value);
	free(field);
}

static const char *own_key(const struct json_token *tok)
{
	return tok->depth > 0 ? tok->path[tok->depth - 1].key : NULL;
}

/* A member name of the top-level object at the given depth below it. */
static int is_top(const struct json_token *tok, size_t depth, const char *name)
{
	return tok->depth == depth && tok->path[0].key != NULL &&
	    strcmp(tok->path[0].key, name) == 0;
}

/*
 * A line of a .jsonl file: the top-level cwd and relocatedCwd follow the
 * project, any value below the session directory follows the directory.
 */
static void visit_session(struct scan *sc, const struct json_token *tok)
{
	char *value, *moved = NULL;
	int top;

	if (tok->kind != JSON_STRING || tok->is_key || tok->depth == 0)
		return;
	top = is_top(tok, 1, "cwd") || is_top(tok, 1, "relocatedCwd");
	if (!top && sc->rules->old_session_dir == NULL)
		return;
	value = token_string(sc, tok);
	if (top)
		moved = move_project(sc->rules, value);
	if (moved == NULL)
		moved = move_session_dir(sc->rules, value);
	if (moved != NULL)
		rewrite_token(sc, tok, value, moved);
	free(moved);
	free(value);
}

/* The format of sessions-index.json is not pinned down: fields by name. */
static void visit_index(struct scan *sc, const struct json_token *tok)
{
	const char *key;
	char *value, *moved;
	int full;

	if (tok->kind != JSON_STRING || tok->is_key ||
	    (key = own_key(tok)) == NULL)
		return;
	full = strcmp(key, "fullPath") == 0;
	if (!full && strcmp(key, "projectPath") != 0 &&
	    strcmp(key, "originalPath") != 0)
		return;
	value = token_string(sc, tok);
	moved = full ? move_session_dir(sc->rules, value) :
	    move_project(sc->rules, value);
	if (moved != NULL)
		rewrite_token(sc, tok, value, moved);
	free(moved);
	free(value);
}

/*
 * A projects key moves unless the new key is already there, either from
 * the start or from an earlier move: two equal keys would leave Claude Code
 * keeping one of them at random, so the old key stays and is reported.
 */
static void resolve_keys(struct scan *sc)
{
	struct item *k = sc->keys.items;
	size_t n = sc->keys.count, i, j;
	int conflict;

	for (i = 0; i < n; i++) {
		if (k[i].new_value == NULL)
			continue;
		conflict = 0;
		for (j = 0; j < n && !conflict; j++)
			conflict = j != i &&
			    (strcmp(k[j].value, k[i].new_value) == 0 ||
			    (j < i && k[j].new_value != NULL &&
			    strcmp(k[j].new_value, k[i].new_value) == 0));
		if (conflict) {
			add_change(&sc->changes, CHANGE_CONFLICT, sc->file,
			    sc->line, k[i].field, k[i].value, k[i].new_value);
			free(k[i].new_value);
			k[i].new_value = NULL;
			continue;
		}
		add_edit(sc, k[i].start + 1, k[i].end - 1,
		    json_encode_string(k[i].new_value));
		add_change(&sc->changes, CHANGE_REWRITE, sc->file, sc->line,
		    k[i].field, k[i].value, k[i].new_value);
	}
	clear_items(&sc->keys);
}

/*
 * Removes the flagged items of an array or an object (r[i] covers a whole
 * element or member). Each takes the separator before it along, or the one
 * after it when nothing before it stays, so the rest keeps its layout.
 */
static void drop_ranges(struct scan *sc, const struct range *r, size_t n,
    const char *removed)
{
	size_t i, k;

	for (i = 0; i < n; i++) {
		if (!removed[i])
			continue;
		for (k = 0; k < i && removed[k]; k++)
			;
		if (k < i) {
			add_edit(sc, r[i - 1].end, r[i].end, xstrdup(""));
		} else if (i == 0) {
			/* The whole leading run goes in one edit. */
			for (k = 1; k < n && removed[k]; k++)
				;
			add_edit(sc, r[0].start, k < n ? r[k].start : r[n - 1].end,
			    xstrdup(""));
		}
	}
}

/* A githubRepoPaths element that would repeat another one goes. */
static void resolve_elems(struct scan *sc)
{
	struct item *e = sc->elems.items;
	struct range *r;
	size_t n = sc->elems.count, i, j;
	const char *other;
	char *removed;

	removed = xmalloc(n + 1);
	memset(removed, 0, n + 1);
	for (i = 0; i < n; i++) {
		if (e[i].new_value == NULL)
			continue;
		for (j = 0; j < n; j++) {
			/* Of two moved elements the first one stays. */
			if (j == i || removed[j] || e[j].value == NULL ||
			    (e[j].new_value != NULL && j > i))
				continue;
			other = e[j].new_value != NULL ? e[j].new_value :
			    e[j].value;
			if (strcmp(other, e[i].new_value) == 0) {
				removed[i] = 1;
				break;
			}
		}
	}
	r = xmalloc((n + 1) * sizeof *r);
	for (i = 0; i < n; i++) {
		r[i].start = e[i].start;
		r[i].end = e[i].end;
		if (removed[i]) {
			add_change(&sc->changes, CHANGE_REMOVE, sc->file,
			    sc->line, e[i].field, e[i].value, NULL);
		} else if (e[i].new_value != NULL) {
			add_edit(sc, e[i].start + 1, e[i].end - 1,
			    json_encode_string(e[i].new_value));
			add_change(&sc->changes, CHANGE_REWRITE, sc->file,
			    sc->line, e[i].field, e[i].value, e[i].new_value);
		}
	}
	drop_ranges(sc, r, n, removed);
	free(r);
	free(removed);
	clear_items(&sc->elems);
}

/* .claude.json: projects keys and githubRepoPaths elements, top level only. */
static void visit_config(struct scan *sc, const struct json_token *tok)
{
	char *value;

	if (tok->is_key) {
		if (is_top(tok, 2, "projects")) {
			value = xstrdup(tok->path[1].key);
			add_item(&sc->keys, tok, value,
			    move_project(sc->rules, value), xstrdup("projects"));
		}
		return;
	}
	if (tok->kind == JSON_OBJECT && is_top(tok, 1, "projects")) {
		resolve_keys(sc);
		return;
	}
	if (is_top(tok, 3, "githubRepoPaths") && tok->path[1].key != NULL &&
	    tok->path[2].key == NULL) {
		value = tok->kind == JSON_STRING ? token_string(sc, tok) : NULL;
		add_item(&sc->elems, tok, value,
		    value != NULL ? move_project(sc->rules, value) : NULL,
		    field_name(tok->path, tok->depth));
		return;
	}
	if (tok->kind == JSON_ARRAY && is_top(tok, 2, "githubRepoPaths") &&
	    tok->path[1].key != NULL)
		resolve_elems(sc);
}

/* An element of a githubRepoPaths array, not a key and not deeper. */
static int is_github_elem(const struct json_token *tok)
{
	return !tok->is_key && is_top(tok, 3, "githubRepoPaths") &&
	    tok->path[1].key != NULL && tok->path[2].key == NULL;
}

static int is_github_array(const struct json_token *tok)
{
	return tok->kind == JSON_ARRAY && !tok->is_key &&
	    is_top(tok, 2, "githubRepoPaths") && tok->path[1].key != NULL;
}

/* Drops the flagged githubRepoPaths elements; the arrays keep their layout. */
static void visit_drop(struct scan *sc, const struct json_token *tok)
{
	struct item *e;
	struct range *r;
	char *removed;
	size_t n, i, left;

	if (is_github_elem(tok)) {
		add_item(&sc->elems, tok, tok->kind == JSON_STRING ?
		    token_string(sc, tok) : NULL, NULL,
		    field_name(tok->path, tok->depth));
		return;
	}
	if (!is_github_array(tok))
		return;
	e = sc->elems.items;
	n = sc->elems.count;
	removed = xmalloc(n + 1);
	r = xmalloc((n + 1) * sizeof *r);
	for (i = 0, left = n; i < n; i++) {
		removed[i] = sc->drop[sc->drop_index++] && e[i].value != NULL;
		r[i].start = e[i].start;
		r[i].end = e[i].end;
		if (removed[i]) {
			add_change(&sc->changes, CHANGE_DROP, sc->file, 0,
			    e[i].field, e[i].value, NULL);
			left--;
		}
	}
	/* An emptied array is written as Claude Code writes one: []. */
	if (left == 0 && n > 0)
		add_edit(sc, tok->start, tok->end, xstrdup("[]"));
	else
		drop_ranges(sc, r, n, removed);
	free(r);
	free(removed);
	clear_items(&sc->elems);
}

static void visit(const struct json_token *tok, void *ctx)
{
	struct scan *sc = ctx;

	if (sc->drop != NULL) {
		visit_drop(sc, tok);
		return;
	}
	switch (sc->kind) {
	case REWRITE_SESSION:
		visit_session(sc, tok);
		break;
	case REWRITE_INDEX:
		visit_index(sc, tok);
		break;
	case REWRITE_CONFIG:
		visit_config(sc, tok);
		break;
	}
}

static int compare_edits(const void *a, const void *b)
{
	const struct edit *x = a, *y = b;

	if (x->start != y->start)
		return x->start < y->start ? -1 : 1;
	return x->end < y->end ? -1 : x->end > y->end;
}

/* Everything outside the edits is copied byte for byte. */
static char *apply_edits(struct scan *sc, size_t len, size_t *out_len)
{
	size_t i, n, pos = 0, size = len;
	char *out, *q;

	qsort(sc->edits, sc->edit_count, sizeof *sc->edits, compare_edits);
	for (i = 0; i < sc->edit_count; i++)
		size += strlen(sc->edits[i].text) -
		    (sc->edits[i].end - sc->edits[i].start);
	q = out = xmalloc(size + 1);
	for (i = 0; i < sc->edit_count; i++) {
		memcpy(q, sc->text + pos, sc->edits[i].start - pos);
		q += sc->edits[i].start - pos;
		n = strlen(sc->edits[i].text);
		memcpy(q, sc->edits[i].text, n);
		q += n;
		pos = sc->edits[i].end;
	}
	memcpy(q, sc->text + pos, len - pos);
	q += len - pos;
	*q = '\0';
	*out_len = (size_t)(q - out);
	return out;
}

/* Scans sc->text, then makes *out and hands the changes over to plan. */
static int run_scan(struct scan *sc, size_t len, struct change_list *plan,
    char **out, size_t *out_len)
{
	size_t i;
	int valid;

	*out = NULL;
	*out_len = 0;
	valid = json_scan(sc->text, len, visit, sc) == 0;
	if (valid && sc->edit_count > 0)
		*out = apply_edits(sc, len, out_len);
	if (valid && plan != NULL) {
		for (i = 0; i < sc->changes.count; i++) {
			if (plan->count == plan->cap) {
				plan->cap = plan->cap ? plan->cap * 2 : 16;
				plan->items = xrealloc(plan->items,
				    plan->cap * sizeof *plan->items);
			}
			plan->items[plan->count++] = sc->changes.items[i];
		}
		sc->changes.count = 0;
	}
	change_list_free(&sc->changes);
	for (i = 0; i < sc->edit_count; i++)
		free(sc->edits[i].text);
	free(sc->edits);
	clear_items(&sc->keys);
	free(sc->keys.items);
	clear_items(&sc->elems);
	free(sc->elems.items);
	return valid ? REWRITE_OK : REWRITE_INVALID;
}

/*
 * Rewrites one JSON text by the rules of its kind. *out is the new text, or
 * NULL when nothing changes. The changes, conflicts included, are added to
 * plan when it is not NULL. Invalid JSON changes nothing.
 */
int rewrite_text(const char *text, size_t len, enum rewrite_kind kind,
    const struct rewrite_rules *rules, const char *file, size_t line,
    struct change_list *plan, char **out, size_t *out_len)
{
	struct scan sc;

	memset(&sc, 0, sizeof sc);
	sc.text = text;
	sc.kind = kind;
	sc.rules = rules;
	sc.file = file;
	sc.line = line;
	return run_scan(&sc, len, plan, out, out_len);
}

/*
 * A .jsonl file goes line by line, so a line that does not parse (such as
 * a last line Claude Code is still writing) passes unchanged. The first
 * pass only plans; the second one writes, and only when something changes.
 */
static int rewrite_session_file(const char *file,
    const struct rewrite_rules *rules, struct change_list *plan, int apply)
{
	struct atomic_file *af = NULL;
	struct timespec times[2];
	struct stat st;
	FILE *in;
	char *line = NULL, *out;
	size_t cap = 0, len, out_len, lineno, changed = 0;
	ssize_t n;
	int pass, saved, nl, failed;

	for (pass = 0; pass < 2; pass++) {
		in = fopen(file, "r");
		if (in == NULL)
			goto fail;
		if (pass == 0) {
			if (fstat(fileno(in), &st) != 0) {
				saved = errno;
				fclose(in);
				errno = saved;
				goto fail;
			}
		} else {
			af = atomic_open(file, st.st_mode);
			if (af == NULL) {
				saved = errno;
				fclose(in);
				errno = saved;
				goto fail;
			}
		}
		lineno = 0;
		failed = 0;
		while (!failed && (n = getline(&line, &cap, in)) > 0) {
			lineno++;
			len = (size_t)n;
			nl = line[len - 1] == '\n';
			if (nl)
				len--;
			rewrite_text(line, len, REWRITE_SESSION, rules, file,
			    lineno, pass == 0 ? plan : NULL, &out, &out_len);
			if (out != NULL)
				changed++;
			if (pass == 1)
				failed = out != NULL ?
				    atomic_write(af, out, out_len) != 0 :
				    atomic_write(af, line, len) != 0;
			if (pass == 1 && !failed && nl)
				failed = atomic_write(af, "\n", 1) != 0;
			free(out);
		}
		if (failed || ferror(in)) {
			saved = errno;
			fclose(in);
			if (af != NULL)
				atomic_abort(af);
			errno = saved;
			goto fail;
		}
		fclose(in);
		if (pass == 0 && (changed == 0 || !apply))
			break;
	}
	free(line);
	if (af != NULL) {
		platform_file_times(&st, times);
		return atomic_commit(af, times) == 0 ? REWRITE_OK : REWRITE_ERROR;
	}
	return REWRITE_OK;
fail:
	saved = errno;
	free(line);
	errno = saved;
	return REWRITE_ERROR;
}

/*
 * Plans the changes of one file and, with apply, makes them. Session files
 * keep their times, as /resume sorts by them; .claude.json gets a fresh
 * one, being really changed, and its first change in a run (tracked by
 * *backup_done) copies it to .claude.json.bak first. A missing
 * .claude.json has nothing to change.
 */
int rewrite_file(const char *file, enum rewrite_kind kind,
    const struct rewrite_rules *rules, struct change_list *plan, int apply,
    int *backup_done)
{
	char *data, *out;
	size_t len, out_len;
	int status, saved;

	if (kind == REWRITE_SESSION)
		return rewrite_session_file(file, rules, plan, apply);
	if (file_read(file, &data, &len) != 0)
		return kind == REWRITE_CONFIG && errno == ENOENT ? REWRITE_OK :
		    REWRITE_ERROR;
	status = rewrite_text(data, len, kind, rules, file, 0, plan, &out,
	    &out_len);
	free(data);
	if (status != REWRITE_OK || out == NULL || !apply) {
		free(out);
		return status;
	}
	if (kind == REWRITE_CONFIG)
		status = config_write(file, out, out_len, backup_done);
	else
		status = file_replace(file, out, out_len, 1);
	saved = errno;
	free(out);
	errno = saved;
	return status == 0 ? REWRITE_OK : REWRITE_ERROR;
}

/*
 * Writes .claude.json anew. It gets a fresh time, being really changed, and
 * the first change in a run (tracked by *backup_done) copies the old file
 * to .claude.json.bak first. A missing file is created, readable only by
 * its owner, as Claude Code creates it.
 */
int config_write(const char *file, const char *data, size_t len,
    int *backup_done)
{
	struct atomic_file *af;
	struct stat st;
	char *backup;
	int status, saved;

	if (stat(file, &st) != 0) {
		if (errno != ENOENT || (af = atomic_open(file, 0600)) == NULL)
			return -1;
		if (atomic_write(af, data, len) != 0) {
			saved = errno;
			atomic_abort(af);
			errno = saved;
			return -1;
		}
		return atomic_commit(af, NULL);
	}
	if (!*backup_done) {
		backup = xmalloc(strlen(file) + 5);
		strcpy(backup, file);
		strcat(backup, ".bak");
		status = file_backup(file, backup);
		saved = errno;
		free(backup);
		if (status != 0) {
			errno = saved;
			return -1;
		}
		*backup_done = 1;
	}
	return file_replace(file, data, len, 0);
}

/* A member of the projects object, raw bytes, quotes and brackets included. */
struct member {
	size_t key_start, key_end, value_start, value_end;
	char *key;
};

/* Where things are in .claude.json, for taking out and putting back a key. */
struct layout {
	int top;		/* the root is an object */
	size_t top_start, top_end;
	int first_key, first_value;	/* the first top-level member */
	size_t key_start, key_end, value_start;
	size_t last_end;	/* end of the last top-level value */
	int projects;		/* projects is an object */
	size_t projects_key_end, projects_start, projects_end;
	struct member *members;
	size_t count, cap;
};

static void layout_clear_members(struct layout *l)
{
	size_t i;

	for (i = 0; i < l->count; i++)
		free(l->members[i].key);
	l->count = 0;
}

/* Of two projects keys the last one counts, as with JSON.parse. */
static void visit_layout(const struct json_token *tok, void *ctx)
{
	struct layout *l = ctx;
	struct member *m;
	int in_projects;

	if (tok->depth == 0) {
		l->top = tok->kind == JSON_OBJECT;
		l->top_start = tok->start;
		l->top_end = tok->end;
		return;
	}
	if (tok->path[0].key == NULL)
		return;
	in_projects = strcmp(tok->path[0].key, "projects") == 0;
	if (tok->depth == 1 && tok->is_key) {
		if (!l->first_key) {
			l->first_key = 1;
			l->key_start = tok->start;
			l->key_end = tok->end;
		}
		if (in_projects) {
			layout_clear_members(l);
			l->projects = 0;
			l->projects_key_end = tok->end;
		}
	} else if (tok->depth == 1) {
		if (!l->first_value) {
			l->first_value = 1;
			l->value_start = tok->start;
		}
		l->last_end = tok->end;
		if (in_projects && tok->kind == JSON_OBJECT) {
			l->projects = 1;
			l->projects_start = tok->start;
			l->projects_end = tok->end;
		}
	} else if (tok->depth == 2 && in_projects && tok->is_key) {
		if (l->count == l->cap) {
			l->cap = l->cap ? l->cap * 2 : 16;
			l->members = xrealloc(l->members,
			    l->cap * sizeof *l->members);
		}
		m = &l->members[l->count++];
		m->key_start = tok->start;
		m->key_end = tok->end;
		m->value_start = m->value_end = tok->end;
		m->key = xstrdup(tok->path[1].key);
	} else if (tok->depth == 2 && in_projects && l->count > 0) {
		l->members[l->count - 1].value_start = tok->start;
		l->members[l->count - 1].value_end = tok->end;
	}
}

static int layout_scan(const char *text, size_t len, struct layout *l)
{
	memset(l, 0, sizeof *l);
	if (json_scan(text, len, visit_layout, l) != 0 || !l->top)
		return REWRITE_INVALID;
	return REWRITE_OK;
}

static void layout_free(struct layout *l)
{
	layout_clear_members(l);
	free(l->members);
}

static char *slice(const char *text, size_t start, size_t end)
{
	char *s;

	s = xmalloc(end - start + 1);
	memcpy(s, text + start, end - start);
	s[end - start] = '\0';
	return s;
}

/*
 * Takes the projects entry of key out of a .claude.json text. *value gets
 * its raw JSON (NULL when there is none) and *out the text without it. The
 * rest stays byte for byte; an emptied projects becomes {}, as Claude Code
 * writes it.
 */
int config_take_project(const char *text, size_t len, const char *key,
    char **value, char **out, size_t *out_len)
{
	struct layout l;
	struct scan sc;
	struct range *r;
	char *removed;
	size_t i, n, last = 0, hits = 0;

	*value = *out = NULL;
	*out_len = 0;
	if (layout_scan(text, len, &l) != REWRITE_OK) {
		layout_free(&l);
		return REWRITE_INVALID;
	}
	n = l.count;
	removed = xmalloc(n + 1);
	r = xmalloc((n + 1) * sizeof *r);
	for (i = 0; i < n; i++) {
		r[i].start = l.members[i].key_start;
		r[i].end = l.members[i].value_end;
		removed[i] = strcmp(l.members[i].key, key) == 0;
		if (removed[i]) {
			last = i;
			hits++;
		}
	}
	if (l.projects && hits > 0) {
		memset(&sc, 0, sizeof sc);
		sc.text = text;
		*value = slice(text, l.members[last].value_start,
		    l.members[last].value_end);
		if (hits == n)
			add_edit(&sc, l.projects_start + 1, l.projects_end - 1,
			    xstrdup(""));
		else
			drop_ranges(&sc, r, n, removed);
		*out = apply_edits(&sc, len, out_len);
		for (i = 0; i < sc.edit_count; i++)
			free(sc.edits[i].text);
		free(sc.edits);
	}
	free(r);
	free(removed);
	layout_free(&l);
	return REWRITE_OK;
}

/* The indentation of a line break in ws ("\n  " gives "  "); "" without one. */
static const char *indent_of(const char *ws)
{
	const char *nl;

	nl = strrchr(ws, '\n');
	return nl != NULL ? nl + 1 : "";
}

static char *concat(const char *const *parts)
{
	char *s;

	s = xstrdup("");
	for (; *parts != NULL; parts++)
		s = append(s, *parts);
	return s;
}

/*
 * Puts a projects entry back: value is raw JSON, as config_take_project
 * gave it. The new member goes after the last one, with the indentation
 * and separators of the others, or of the top level when projects is empty
 * or missing. REWRITE_EXISTS when key is already there: two equal keys
 * would leave Claude Code keeping one of them at random.
 */
int config_put_project(const char *text, size_t len, const char *key,
    const char *value, char **out, size_t *out_len)
{
	struct layout l;
	struct scan sc;
	char *enc, *quoted, *ws, *inner, *sep, *edit;
	const char *unit;
	size_t i;

	*out = NULL;
	*out_len = 0;
	if (layout_scan(text, len, &l) != REWRITE_OK) {
		layout_free(&l);
		return REWRITE_INVALID;
	}
	for (i = 0; i < l.count; i++)
		if (strcmp(l.members[i].key, key) == 0) {
			layout_free(&l);
			return REWRITE_EXISTS;
		}
	if (!l.projects && l.projects_key_end != 0) {
		/* projects is there, but not an object. */
		layout_free(&l);
		return REWRITE_INVALID;
	}
	memset(&sc, 0, sizeof sc);
	sc.text = text;
	enc = json_encode_string(key);
	quoted = concat((const char *const[]){ "\"", enc, "\"", NULL });
	free(enc);
	ws = l.first_key ? slice(text, l.top_start + 1, l.key_start) :
	    xstrdup("");
	unit = indent_of(ws);
	inner = strchr(ws, '\n') != NULL ?
	    concat((const char *const[]){ ws, unit, NULL }) : xstrdup("");
	if (l.count > 0) {
		free(inner);
		inner = slice(text, l.projects_start + 1, l.members[0].key_start);
		sep = slice(text, l.members[0].key_end,
		    l.members[0].value_start);
		edit = concat((const char *const[]){ ",", inner, quoted, sep,
		    value, NULL });
		add_edit(&sc, l.members[l.count - 1].value_end,
		    l.members[l.count - 1].value_end, edit);
	} else if (l.projects) {
		sep = slice(text, l.projects_key_end, l.projects_start);
		edit = concat((const char *const[]){ inner, quoted, sep, value,
		    strchr(ws, '\n') != NULL ? ws : "", NULL });
		add_edit(&sc, l.projects_start + 1, l.projects_end - 1, edit);
	} else if (l.first_value) {
		sep = slice(text, l.key_end, l.value_start);
		edit = concat((const char *const[]){ ",", ws, "\"projects\"", sep,
		    "{", inner, quoted, sep, value,
		    strchr(ws, '\n') != NULL ? ws : "", "}", NULL });
		add_edit(&sc, l.last_end, l.last_end, edit);
	} else {
		sep = xstrdup(":");
		edit = concat((const char *const[]){ "\"projects\":{", quoted,
		    sep, value, "}", NULL });
		add_edit(&sc, l.top_start + 1, l.top_end - 1, edit);
	}
	*out = apply_edits(&sc, len, out_len);
	for (i = 0; i < sc.edit_count; i++)
		free(sc.edits[i].text);
	free(sc.edits);
	free(sep);
	free(inner);
	free(ws);
	free(quoted);
	layout_free(&l);
	return REWRITE_OK;
}

static void visit_github(const struct json_token *tok, void *ctx)
{
	struct scan *sc = ctx;
	struct github_list *l = sc->github;
	struct github_path *p;

	if (!is_github_elem(tok))
		return;
	if (l->count == l->cap) {
		l->cap = l->cap ? l->cap * 2 : 16;
		l->items = xrealloc(l->items, l->cap * sizeof *l->items);
	}
	p = &l->items[l->count++];
	p->repo = xstrdup(tok->path[1].key);
	p->path = tok->kind == JSON_STRING ? token_string(sc, tok) : NULL;
}

/*
 * Every element of the githubRepoPaths arrays, in the order of the file;
 * config_drop_github takes its flags in the same order.
 */
int config_github_paths(const char *text, size_t len,
    struct github_path **paths, size_t *count)
{
	struct github_list l = { NULL, 0, 0 };
	struct scan sc;

	memset(&sc, 0, sizeof sc);
	sc.text = text;
	sc.github = &l;
	if (json_scan(text, len, visit_github, &sc) != 0) {
		github_paths_free(l.items, l.count);
		*paths = NULL;
		*count = 0;
		return REWRITE_INVALID;
	}
	*paths = l.items;
	*count = l.count;
	return REWRITE_OK;
}

void github_paths_free(struct github_path *paths, size_t count)
{
	size_t i;

	for (i = 0; i < count; i++) {
		free(paths[i].repo);
		free(paths[i].path);
	}
	free(paths);
}

/*
 * Takes out the githubRepoPaths elements flagged in drop (one flag per
 * element of config_github_paths). The rest stays byte for byte.
 */
int config_drop_github(const char *text, size_t len, const char *file,
    const char *drop, struct change_list *plan, char **out, size_t *out_len)
{
	struct scan sc;

	memset(&sc, 0, sizeof sc);
	sc.text = text;
	sc.kind = REWRITE_CONFIG;
	sc.file = file;
	sc.drop = drop;
	return run_scan(&sc, len, plan, out, out_len);
}
